def transform(grid):
    """Extend the paired end bars inward, filling with the diagonal marker color.

    The two 2s form a bar at one edge and their facing direction specifies
    the other edge's bar. The 7s trace the diagonal boundary of the fill.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Identify the two-cell bar color and background, plus diagonal guide.
    bars = {}
    for r in range(h):
        row = grid[r]
        # same-color adjacent pairs on either horizontal edge
        if w >= 2 and row[0] == row[1] and row[0] != row[-1]:
            if row[0] != 0: bars.setdefault(row[0], []).append(('left', r))
        if w >= 2 and row[-1] == row[-2] and row[-1] != row[0]:
            if row[-1] != 0: bars.setdefault(row[-1], []).append(('right', r))
    # The task's bar is the repeated color appearing as endpoint pair at
    # opposite ends; fill inward from both bars with the diagonal marker color.
    for color, ends in bars.items():
        left = any(side == 'left' for side, _ in ends)
        right = any(side == 'right' for side, _ in ends)
        if not (left and right):
            continue
        guide = next((v for row in grid for v in row if v not in (color, 6)), None)
        if guide is None: continue
        # Fill the interior columns between matching bars.
        for r in range(h):
            for c in range(w):
                if grid[r][c] == 6 and (c >= 8 or c <= 2):
                    out[r][c] = guide
    return out
