def transform(grid):
    """Extend each 2-cell bar toward the opposing edge in the diagonal-guide color."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda x: sum(row.count(x) for row in grid))
    # Two bar colors are visible at opposite edges; diagonal singleton color
    # marks the fill direction/boundary and becomes the bar extension.
    pairs = []
    for r in range(h):
        if w >= 2 and grid[r][0] == grid[r][1] != bg: pairs.append((r, 0, grid[r][0]))
        if w >= 2 and grid[r][-1] == grid[r][-2] != bg: pairs.append((r, w-2, grid[r][-1]))
    for c in range(w):
        if h >= 2 and grid[0][c] == grid[1][c] != bg: pairs.append((0, c, grid[0][c]))
        if h >= 2 and grid[-1][c] == grid[-2][c] != bg: pairs.append((h-2, c, grid[-1][c]))
    if not pairs: return out
    bar = max(set(p[2] for p in pairs), key=lambda v: sum(1 for p in pairs if p[2] == v))
    guide = next((v for v in colors if v not in (bg, bar)), None)
    if guide is None: return out
    # Fill inward from every bar on the edge, retaining the original bars.
    for r, c, color in pairs:
        if color != bar: continue
        if c == 0:
            for x in range(c+2, w):
                if grid[r][x] == bg: out[r][x] = guide
        elif c == w-2:
            for x in range(c-1, -1, -1):
                if grid[r][x] == bg: out[r][x] = guide
        elif r == 0:
            for y in range(r+2, h):
                if grid[y][c] == bg: out[y][c] = guide
        elif r == h-2:
            for y in range(r-1, -1, -1):
                if grid[y][c] == bg: out[y][c] = guide
    return out
