    """Fill the rectangle bracketed by two corner bars, with diagonal guides as boundary."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row: counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    # Locate monochrome bars along top/bottom rows or left/right columns.
    bars = []
    for r,row in enumerate(grid):
        c=0
        while c<w:
            d=c+1
            while d<w and row[d]==row[c] and row[c]!=bg: d+=1
            if d-c>=2: bars.append(('h',r,c,d-1,row[c]))
            c=d
    for c in range(w):
        r=0
        while r<h:
            d=r+1
            while d<h and grid[d][c]==grid[r][c] and grid[r][c]!=bg: d+=1
            if d-r>=2: bars.append(('v',c,r,d-1,grid[r][c]))
            r=d
    guides={v for v in counts if v not in (bg,) and v not in [b[4] for b in bars]}
    if not bars: return out
    # Choose the pair of border bars spanning opposite corners; fill their
    # rectangular interior in the guide color, retaining guide-color edges.
    hbars=[b for b in bars if b[0]=='h']
    vbars=[b for b in bars if b[0]=='v']
    if len(hbars)>=2:
        top=min(hbars,key=lambda b:b[1]); bottom=max(hbars,key=lambda b:b[1])
        c0=min(top[2],bottom[2]); c1=max(top[3],bottom[3])
        r0,r1=top[1],bottom[1]
    elif len(vbars)>=2:
        left=min(vbars,key=lambda b:b[1]); right=max(vbars,key=lambda b:b[1])
        r0=min(left[2],right[2]); r1=max(left[3],right[3])
        c0,c1=left[1],right[1]
    else:
        return out
    # In observed task, the singleton diagonal guides are recolored 4 and
    # the expanding interior is painted with the singleton's original color.
    guide=next(iter(guides),None)
    if guide is None: return out
    mark=next((v for v in counts if v not in (bg,guide) and counts[v] <= 4), None)
    if mark is None: mark=guide
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if grid[r][c]==bg: out[r][c]=guide
    # diagonal points become 4 (the distinguishing color in the demo)
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (bg,guide) and counts[grid[r][c]] <= 4:
                out[r][c]=4
    return out
