def transform(grid):
    """Extend matched corner bars along two perpendicular edges; diagonal seeds identify the stripe color."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row: counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    # Locate two-cell bars at corners, their length and position anchor a 2-wide stripe.
    bars = []
    for r,row in enumerate(grid):
        if row[0] == row[1] != bg: bars.append(('left',r,row[0]))
        if row[-1] == row[-2] != bg: bars.append(('right',r,row[-1]))
        if row[0] == row[-1] and row[0] != bg: pass
    guides = [v for v,n in counts.items() if v != bg and n <= 3]
    if not bars: return out
    # Pick guide color occurring as isolated diagonal pixels, recolor these as 4.
    guide = next((v for v in guides if any(
        0 < r < h-1 and 0 < c < w-1 and grid[r][c] == v and
        grid[r-1][c-1] == bg and grid[r+1][c+1] == bg
        for r in range(h) for c in range(w))), None)
    if guide is None: return out
    for r in range(h):
        for c in range(w):
            if grid[r][c] == guide: out[r][c] = 4
    # Corner pair at the top-right fills down a two-cell-wide right stripe,
    # and bottom-left pair fills upward/along a two-cell-wide left stripe.
    top_right = next((r for r in range(h) if grid[r][-1] == grid[r][-2] != bg), None)
    bottom_left = next((r for r in range(h-1,-1,-1) if grid[r][0] == grid[r][1] != bg), None)
    if top_right is not None:
        fill = grid[top_right][-1]
        for r in range(top_right, h):
            for c in range(w-2, w):
                if grid[r][c] == bg: out[r][c] = fill
    if bottom_left is not None:
        fill = grid[bottom_left][0]
        for r in range(0, bottom_left+1):
            for c in range(0, 2):
                if grid[r][c] == bg: out[r][c] = fill
    return out
