def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for x in row: counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)
    # Opposite corner bars are equal-length horizontal segments. The sparse
    # diagonal color extends their inward lanes; guide cells turn to 4.
    bars = []
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            e = c + 1
            while e < w and row[e] == row[c] and row[c] != bg: e += 1
            if e-c >= 2 and (c == 0 or e == w):
                bars.append((r, c, e, row[c]))
            c = e
    if len(bars) < 2:
        return out
    barcols = {b[3] for b in bars}
    marker = next((v for v in counts if v != bg and v not in barcols), None)
    if marker is None:
        return out
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                out[r][c] = 4
    # corner bars project inward in parallel lanes whose width is half their length
    for r, c, e, color in bars:
        lane = max(1, (e-c)//2)
        if c == 0:
            for y in range(r-1, -1, -1):
                for x in range(c, min(c+lane,w)):
                    if grid[y][x] == bg: out[y][x] = marker
