def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row: counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    # Find horizontal bars touching opposite corners.
    bars = []
    for r, row in enumerate(grid):
        if row[0] == row[1] != bg:
            end = 2
            while end < w and row[end] == row[0]: end += 1
            if end < w: bars.append(('left', r, 0, end, row[0]))
        if row[-1] == row[-2] != bg:
            start = w-2
            while start > 0 and row[start-1] == row[-1]: start -= 1
            if start > 0: bars.append(('right', r, start, w, row[-1]))
    if len(bars) < 2:
        return out
    barcolors = {b[4] for b in bars}
    marker_color = next((v for v in counts if v != bg and v not in barcolors), None)
    if marker_color is None:
        return out
    markers = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == marker_color]
    for r,c in markers:
        out[r][c] = 4
    left = next((b for b in bars if b[0] == 'left'), None)
    right = next((b for b in bars if b[0] == 'right'), None)
    if left and right:
        # The right/top bar's inward lane runs the full distance to the opposite edge.
        _, rr, c0, c1, _ = right
        for r in range(rr+1, h):
            for c in range(c0, c1):
                if grid[r][c] == bg: out[r][c] = marker_color
        # The left/bottom lane begins just beyond the diagonal marker chain.
        _, lr, c0, c1, _ = left
        marker_rows = [r for r,c in markers if c0 <= c < c1]
        start = max(marker_rows, default=lr-1) + 1
        for r in range(start, lr):
            for c in range(c0, c1):
                if grid[r][c] == bg: out[r][c] = marker_color
    return out
