def transform(grid):
    """Extend matched boundary bars inward; recolor isolated guide marks to 4."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row: counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    # Bars are contiguous same-color runs of length >= 2 at an edge.
    bars = []
    for r, row in enumerate(grid):
        for start, end in ((0, 1), (w-2, w-1)):
            if row[start] == row[end] != background:
                color = row[start]
                # Dots away from bars mark a reflected/enlarged corridor.
                bars.append((r, start, end+1, color))
    # Diagonal singleton objects are emphasized as 4; bar extension is still
    # determined by the corner-bar axes, not by the marker values themselves.
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != background and counts[v] <= 3:
                out[r][c] = 4
    # Extend each horizontal edge bar inward in its two-column width, with the
    # most common non-background color that is not the bar's own color.
    for r, a, b, color in bars:
        fill = next((v for v in counts if v != background and v != color), None)
        if fill is None: continue
        if a == 0:
            for y in range(r-1, -1, -1):
                for x in range(a, b):
                    if grid[y][x] == background: out[y][x] = fill
        else:
            for y in range(r+1, h):
                for x in range(a, b):
                    if grid[y][x] == background: out[y][x] = fill
    return out
